namespace ghidra.app.plugin.core.debug.service.modules;



using ghidra.debug.api.modules;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.trace.model;

public abstract class AbstractMapEntry<T, P> : MapEntry<T, P> {
	protected Trace fromTrace;
	protected T fromObject;
	protected long snap;
	protected Program toProgram;
	protected P toObject;

	public AbstractMapEntry(Trace fromTrace, T fromObject, long snap, Program toProgram,
			P toObject) {
		this.fromTrace = fromTrace;
		this.fromObject = fromObject;
		this.snap = snap;
		this.toProgram = toProgram;
		this.toObject = toObject;
	}

	/* @Override */
	public bool equals(object obj) {
		// TODO: I guess comparing only the "from" object is sufficient....
		if (!(obj is AbstractMapEntry<object,object>)) {
			return false;
		}
		AbstractMapEntry<object,object> that = (AbstractMapEntry<object,object>) obj;
		return this.fromObject == that.fromObject;
	}

	/* @Override */
	public int hashCode() {
		return Objects.hash(fromObject);
	}

	/* @Override */
	public Trace getFromTrace() {
		return fromTrace;
	}

	/* @Override */
	public T getFromObject() {
		return fromObject;
	}

	/* @Override */
	public Lifespan getFromLifespan() {
		return Lifespan.nowOn(snap);
	}

	/* @Override */
	public TraceLocation getFromTraceLocation() {
		return new DefaultTraceLocation(fromTrace, null, getFromLifespan(),
			getFromRange().getMinAddress());
	}

	protected void setToObject(Program toProgram, P toObject) {
		this.toProgram = toProgram;
		this.toObject = toObject;
	}

